MATCH (am:AircraftModel)
WHERE any(a IN am.aliases WHERE a CONTAINS "MD-80") OR am.name CONTAINS "MD-80"
RETURN am.name AS model, am.wingspan_metre AS wingspan_metre;

MATCH (am:AircraftModel)-[:manufacturedBy]->(man:AircraftManufacturer)
WHERE any(a IN am.aliases WHERE a CONTAINS 'S-92') OR am.name CONTAINS 'S-92'
RETURN man.name AS Manufacturer, am.first_flight AS LaunchYear;

MATCH (fa:FlightAccident)-[:involves]->(m:AircraftModel)
WHERE fa.flight_number = '2193' OR fa.name CONTAINS 'Pegasus Airlines Flight 2193'
RETURN m.name AS ModelName, m.service_entry AS ServiceEntryDate;

MATCH (fa:FlightAccident)-[:departsFrom]->(ap:Airport)
WHERE fa.name CONTAINS 'South African Airways Flight 201'
RETURN ap.name AS departure_airport_name;
